                            onSelectEvent={setEvent}
                            onChangeInputs={setInputs}
                            onToggle={onToggle}
                            testRun={
                                <AutomationTestRunButton
                                    automation={automation}
                                    base={base}
                                    dirty={dirty}
                                />
                            }
                            actions={
                                <AutomationActionsMenu
                                    automation={automation}
