                                                className="size-3.5 shrink-0 text-primary"
                                                weight="bold"
                                            />
                                        ) : null}
                                    </span>
                                    {card.description ? (
                                        <span className="line-clamp-2 text-xs text-muted-foreground">
                                            {card.description}
                                        </span>
                                    ) : null}
                                </button>
                            )
                        })}
                    </div>
                </div>
            ))}
